@Test
void testArtifactResolverRequestEquality() {
    Session session = mock(Session.class);
    ArtifactCoordinates coords1 = mock(ArtifactCoordinates.class);
    ArtifactCoordinates coords2 = mock(ArtifactCoordinates.class);
    RemoteRepository repo1 = mock(RemoteRepository.class);
    RemoteRepository repo2 = mock(RemoteRepository.class);
    List<RemoteRepository> repositories1 = Arrays.asList(repo1, repo2);
    List<RemoteRepository> repositories2 = Arrays.asList(repo1, repo2);
    ArtifactResolverRequest.ArtifactResolverRequestBuilder builder = ArtifactResolverRequest.builder();
    ArtifactResolverRequest request1 = builder.session(session).coordinates(Arrays.asList(coords1, coords2)).repositories(repositories1).build();
    ArtifactResolverRequest request2 = builder.session(session).coordinates(Arrays.asList(coords1, coords2)).repositories(repositories2).build();
    ArtifactResolverRequest request3 = builder.session(session).coordinates(// Different order
    Arrays.asList(coords2, coords1)).repositories(repositories1).build();
    // Test equals and hashCode
    assertEquals(request1, request2);
    assertEquals(request1.hashCode(), request2.hashCode());
    assertNotEquals(request1, request3);
    // Test toString
    String toString = request1.toString();
    assertTrue(toString.contains("coordinates="), "Expected " + toString + " to contain " + "coordinates=");
    assertTrue(toString.contains("repositories="), "Expected " + toString + " to contain " + "repositories=");
}

