    MavenSession session = mock(MavenSession.class);
    MavenExecutionRequest executionRequest = new DefaultMavenExecutionRequest();
    when(session.getRequest()).thenReturn(executionRequest);
    Session sessionv4 = mock(Session.class);
    when(session.getSession()).thenReturn(sessionv4);
    when(sessionv4.getToolchains()).thenReturn(List.of(ToolchainModel.newBuilder().type("basic").build(), ToolchainModel.newBuilder().type("rare").build()));
    org.apache.maven.api.Toolchain basicPrivate = mock(org.apache.maven.api.Toolchain.class);
    when(basicPrivate.matchesRequirements(anyMap())).thenReturn(false);
    when(basicPrivate.matchesRequirements(ArgumentMatchers.eq(Map.of("key", "value")))).thenReturn(true);
    when(toolchainFactoryBasicType.createToolchain(isA(org.apache.maven.api.toolchain.ToolchainModel.class))).thenReturn(basicPrivate);
    List<Toolchain> toolchains = toolchainManager.getToolchains(session, "basic", Collections.singletonMap("key", "value"));
    assertEquals(1, toolchains.size());
}

