@Test
void testDependencyResolverRequestEquality() {
    Session session = mock(Session.class);
    DependencyResolverRequest.DependencyResolverRequestBuilder builder = DependencyResolverRequest.builder();
    DependencyResolverRequest request1 = builder.session(session).requestType(DependencyResolverRequest.RequestType.COLLECT).pathScope(PathScope.MAIN_COMPILE).build();
    DependencyResolverRequest request2 = builder.session(session).requestType(DependencyResolverRequest.RequestType.COLLECT).pathScope(PathScope.MAIN_COMPILE).build();
    DependencyResolverRequest request3 = builder.session(session).requestType(DependencyResolverRequest.RequestType.RESOLVE).pathScope(PathScope.MAIN_COMPILE).build();
    assertEquals(request1, request2);
    assertEquals(request1.hashCode(), request2.hashCode());
    assertNotEquals(request1, request3);
    String toString = request1.toString();
    assertTrue(toString.contains("requestType="), "Expected " + toString + " to contain " + "requestType=");
    assertTrue(toString.contains("pathScope="), "Expected " + toString + " to contain " + "pathScope=");
}
